package compress

import (
	"bytes"
	"compress/flate"
	"testing"
)

// TestMSZIPFixtures decodes real MSZIP cabinets (generated by Microsoft's own
// compressor; see testdata/README.md) and checks the output byte-for-byte against
// the committed plaintext. mszip-multi.cab holds ~64 KB across several blocks, so
// it exercises the part MSZIP cannot get right by decoding blocks in isolation:
// every block after the first is compressed against its predecessor's output as a
// preset dictionary.
func TestMSZIPFixtures(t *testing.T) {
	cases := []struct {
		cab   string
		files []string
	}{
		{"mszip-multi.cab", []string{"readme.txt", "code.bin"}},
		{"mszip-single.cab", []string{"hello.txt"}},
	}
	for _, tc := range cases {
		t.Run(tc.cab, func(t *testing.T) {
			cab, err := ReadCabinet(readFixture(t, tc.cab))
			if err != nil {
				t.Fatal(err)
			}
			// Guard against a vacuous test: makecab silently falls back to storing
			// when it cannot compress, and a stored cabinet would decode correctly
			// without any of the code under test.
			if got := cab.folders[0].typeCompress & compMask; got != compMSZIP {
				t.Fatalf("fixture folder compression = %d, want MSZIP (%d)", got, compMSZIP)
			}
			if got := len(cab.Files()); got != len(tc.files) {
				t.Fatalf("file count = %d, want %d", got, len(tc.files))
			}
			for _, name := range tc.files {
				f, ok := cab.Find(name)
				if !ok {
					t.Errorf("%s: not present in cabinet", name)
					continue
				}
				got, err := cab.Data(f)
				if err != nil {
					t.Errorf("%s: %v", name, err)
					continue
				}
				want := readFixture(t, name)
				if !bytes.Equal(got, want) {
					t.Errorf("%s: mismatch (got %d bytes, want %d, firstDiff %d)",
						name, len(got), len(want), firstDiff(got, want))
				}
			}
		})
	}
}

// TestMSZIPMultiBlockDictionary pins the property the multi-block fixture exists
// to test. A block's deflate stream may reference matches reaching back into the
// previous block's output, so decoding each block with an empty dictionary
// corrupts everything after the first — this asserts the fixture really does span
// several blocks, keeping that path covered if the fixture is ever regenerated.
func TestMSZIPMultiBlockDictionary(t *testing.T) {
	cab, err := ReadCabinet(readFixture(t, "mszip-multi.cab"))
	if err != nil {
		t.Fatal(err)
	}
	if got := cab.folders[0].blocks; got < 2 {
		t.Fatalf("fixture folder has %d CFDATA block(s), want several to cover the preset dictionary", got)
	}
}

// mszipEncode builds a folder's worth of MSZIP blocks from the given plaintext
// blocks, compressing each against the real MSZIP window: the last 32 KiB of all
// preceding output, not merely the previous block. It is the encoder counterpart
// of mszipDecode, used to reach block layouts makecab does not emit.
func mszipEncode(t *testing.T, plain [][]byte) (blocks [][]byte, lens []int, out []byte) {
	t.Helper()
	for _, blk := range plain {
		dict := out
		if len(dict) > mszipWindowSize {
			dict = dict[len(dict)-mszipWindowSize:]
		}
		var buf bytes.Buffer
		buf.Write(mszipSignature)
		w, err := flate.NewWriterDict(&buf, flate.BestCompression, dict)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := w.Write(blk); err != nil {
			t.Fatal(err)
		}
		if err := w.Close(); err != nil {
			t.Fatal(err)
		}
		blocks = append(blocks, buf.Bytes())
		lens = append(lens, len(blk))
		out = append(out, blk...)
	}
	return blocks, lens, out
}

// TestMSZIPShortBlockWindow covers the case the makecab-produced fixtures cannot
// reach. makecab fills every block but the last to a full 32 KiB, which makes
// "the previous block's output" and "the last 32 KiB of output" the same bytes —
// so a decoder that carries only the previous block decodes those fixtures
// perfectly. When intermediate blocks are short, a block's deflate stream can
// emit a match reaching back past its immediate predecessor, and only the wider
// window can resolve it.
func TestMSZIPShortBlockWindow(t *testing.T) {
	// Three short blocks; the third repeats the first, forcing a match distance
	// that reaches over the second.
	b0 := []byte("ALPHA-alpha-ALPHA-alpha-0123456789")
	b1 := []byte("BETA-beta-BETA-beta-9876543210____")
	b2 := append(append([]byte{}, b0...), b1...)

	blocks, lens, want := mszipEncode(t, [][]byte{b0, b1, b2})
	got, err := mszipDecode(blocks, lens, len(want))
	if err != nil {
		t.Fatalf("decoding short intermediate blocks: %v", err)
	}
	if !bytes.Equal(got, want) {
		t.Errorf("mismatch:\n got %q\nwant %q", got, want)
	}
}

// TestMSZIPRejectsOverlongBlock checks that a block decoding to more than its
// header declares is rejected. Trusting the declared length would truncate the
// block silently and then hand that truncated output to the next block as its
// dictionary, corrupting the rest of the folder while reporting success.
func TestMSZIPRejectsOverlongBlock(t *testing.T) {
	plain := bytes.Repeat([]byte("overlong-block-payload."), 40)
	blocks, lens, _ := mszipEncode(t, [][]byte{plain})

	// Under-declare the block's uncompressed length by a third.
	short := lens[0] * 2 / 3
	got, err := mszipDecode(blocks, []int{short}, short)
	if err == nil {
		t.Fatalf("expected an error for a block that decodes to %d bytes but declares %d; got %d bytes back",
			len(plain), short, len(got))
	}
}

// TestMSZIPRejectsBadSignature checks that a block missing its "CK" marker is
// reported rather than fed to the deflate decoder as-is.
func TestMSZIPRejectsBadSignature(t *testing.T) {
	if _, err := mszipDecode([][]byte{{'X', 'Y', 0x00}}, []int{1}, 1); err == nil {
		t.Error("expected an error for a block without the CK signature")
	}
	// An empty block is shorter than the signature itself — must error, not panic.
	if _, err := mszipDecode([][]byte{{}}, []int{0}, 0); err == nil {
		t.Error("expected an error for an empty block")
	}
}

// TestMSZIPTruncatedBlock checks that a block whose deflate stream ends before the
// declared uncompressed length is an error rather than a short, silently-wrong
// result.
func TestMSZIPTruncatedBlock(t *testing.T) {
	cab, err := ReadCabinet(readFixture(t, "mszip-single.cab"))
	if err != nil {
		t.Fatal(err)
	}
	f, ok := cab.Find("hello.txt")
	if !ok {
		t.Fatal("hello.txt not in fixture")
	}
	want, err := cab.Data(f)
	if err != nil {
		t.Fatal(err)
	}
	// Re-decode the same block with its payload cut in half, keeping the declared
	// output length: the decoder must not return a truncated buffer as success.
	raw := readFixture(t, "mszip-single.cab")
	full, err := ReadCabinet(raw)
	if err != nil {
		t.Fatal(err)
	}
	fld := full.folders[0]
	r := &cursor{b: raw, pos: int(fld.coffCabStart)}
	r.u32()
	cbData := int(r.u16())
	r.u16()
	block := r.take(cbData)
	if r.err != nil {
		t.Fatal(r.err)
	}
	if _, err := mszipDecode([][]byte{block[:len(block)/2]}, []int{len(want)}, len(want)); err == nil {
		t.Error("expected an error decoding a truncated MSZIP block")
	}
}
